#include <stdlib.h>
#include <ctype.h>

int** imageSmoother(int** img, int imgSize, int* imgColSize, int* returnSize, int** returnColumnSizes) {
    int m = imgSize, n = imgColSize[0];
    int** out = (int**)malloc((size_t)m * sizeof(int*));
    *returnColumnSizes = (int*)malloc((size_t)m * sizeof(int));
    *returnSize = m;
    for (int r = 0; r < m; ++r) {
        out[r] = (int*)malloc((size_t)n * sizeof(int));
        (*returnColumnSizes)[r] = n;
        for (int c = 0; c < n; ++c) {
            int sum = 0, count = 0;
            for (int dr = -1; dr <= 1; ++dr) {
                for (int dc = -1; dc <= 1; ++dc) {
                    int nr = r + dr, nc = c + dc;
                    if (0 <= nr && nr < m && 0 <= nc && nc < n) {
                        sum += img[nr][nc];
                        ++count;
                    }
                }
            }
            out[r][c] = sum / count;
        }
    }
    return out;
}

static void skip_space(const char* s, int* p) {
    while (s[*p] && isspace((unsigned char)s[*p])) ++(*p);
}

