int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 1;

    int p = 0;
    skip_space(line, &p);
    if (line[p++] != '[') return 1;          /* arguments array */
    skip_space(line, &p);
    if (line[p++] != '[') return 1;          /* matrix */

    int rowCap = 16, m = 0;
    int** img = (int**)malloc((size_t)rowCap * sizeof(int*));
    int* cols = (int*)malloc((size_t)rowCap * sizeof(int));

    for (;;) {
        skip_space(line, &p);
        if (line[p] == ']') { ++p; break; }
        if (line[p++] != '[') return 1;

