        int* row = (int*)malloc((size_t)colCap * sizeof(int));
        for (;;) {
            skip_space(line, &p);
            if (line[p] == ']') { ++p; break; }
            if (n == colCap) {
                colCap *= 2;
                row = (int*)realloc(row, (size_t)colCap * sizeof(int));
            }
            row[n++] = read_number(line, &p);
            skip_space(line, &p);
            if (line[p] == ',') ++p;
        }

