            img = (int**)realloc(img, (size_t)rowCap * sizeof(int*));
            cols = (int*)realloc(cols, (size_t)rowCap * sizeof(int));
        }
        img[m] = row;
        cols[m] = n;
        ++m;
        skip_space(line, &p);
        if (line[p] == ',') ++p;
    }

    int returnSize = 0;
    int* returnColumnSizes = NULL;
    int** result = imageSmoother(img, m, cols, &returnSize, &returnColumnSizes);

    printf("[");
    for (int i = 0; i < returnSize; ++i) {
        if (i) printf(",");
        printf("[");
        for (int j = 0; j < returnColumnSizes[i]; ++j) {
