static void skipSpace(const string& s, size_t& p) {
    while (p < s.size() && isspace((unsigned char)s[p])) ++p;
}

static vector<vector<int>> parseMatrix(const string& s) {
    vector<vector<int>> mat;
    size_t p = 0;
    skipSpace(s, p);
    if (p >= s.size() || s[p++] != '[') return mat; // arguments
    skipSpace(s, p);
    if (p >= s.size() || s[p++] != '[') return mat; // matrix

    while (true) {
        skipSpace(s, p);
        if (p < s.size() && s[p] == ']') { ++p; break; }
        if (p >= s.size() || s[p++] != '[') break;

        vector<int> row;
        while (true) {
            skipSpace(s, p);
            if (p < s.size() && s[p] == ']') { ++p; break; }
            int value = 0;
            while (p < s.size() && isdigit((unsigned char)s[p])) {
                value = value * 10 + (s[p] - '0');
                ++p;
            }
            row.push_back(value);
            skipSpace(s, p);
            if (p < s.size() && s[p] == ',') ++p;
        }
        mat.push_back(row);
        skipSpace(s, p);
        if (p < s.size() && s[p] == ',') ++p;
    }
    return mat;
}

