public class Main {
    static int[][] parseMatrix(String s) {
        s = s.trim();
        s = s.substring(1, s.length() - 1).trim();
        if (s.isEmpty()) return new int[0][0];
        List<int[]> rows = new ArrayList<>();
        int depth = 0, start = -1;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '[') { if (depth == 0) start = i + 1; depth++; }
            else if (ch == ']') {
                depth--;
                if (depth == 0) {
                    String row = s.substring(start, i);
                    if (row.trim().isEmpty()) rows.add(new int[0]);
                    else {
                        String[] parts = row.split(",");
                        int[] a = new int[parts.length];
                        for (int j = 0; j < parts.length; j++) a[j] = Integer.parseInt(parts[j].trim());
                        rows.add(a);
                    }
                }
            }
        }
        return rows.toArray(new int[0][]);
    }

    static int[][] parseArgs(String line) {
        String outer = line.trim();
        outer = outer.substring(1, outer.length() - 1).trim();
        return parseMatrix(outer);
    }

    static String serialize(int[][] a) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(',');
            sb.append('[');
            for (int j = 0; j < a[i].length; j++) {
                if (j > 0) sb.append(',');
                sb.append(a[i][j]);
            }
            sb.append(']');
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[][] img = parseArgs(line);
        System.out.println(serialize(new Solution().imageSmoother(img)));
    }
}

